// Node hierarchy and its visitor are yours to design: see the task description.
class Node {
public:
    virtual ~Node() = default;
};

Ptr num(double v);
Ptr var(std::string name);
Ptr add(Ptr a, Ptr b);
Ptr sub(Ptr a, Ptr b);
Ptr mul(Ptr a, Ptr b);
Ptr neg(Ptr a);
