void PowNode::accept(FoldVisitor& visitor) const { visitor.visit(*this); }
void PowNode::accept(DiffVisitor& visitor) const { visitor.visit(*this); }

void ExpNode::accept(EvalVisitor& visitor) const { visitor.visit(*this); }
void ExpNode::accept(PrintVisitor& visitor) const { visitor.visit(*this); }
void ExpNode::accept(VarsVisitor& visitor) const { visitor.visit(*this); }
void ExpNode::accept(CloneVisitor& visitor) const { visitor.visit(*this); }
void ExpNode::accept(FoldVisitor& visitor) const { visitor.visit(*this); }
void ExpNode::accept(DiffVisitor& visitor) const { visitor.visit(*this); }

void LogNode::accept(EvalVisitor& visitor) const { visitor.visit(*this); }
void LogNode::accept(PrintVisitor& visitor) const { visitor.visit(*this); }
void LogNode::accept(VarsVisitor& visitor) const { visitor.visit(*this); }
void LogNode::accept(CloneVisitor& visitor) const { visitor.visit(*this); }
void LogNode::accept(FoldVisitor& visitor) const { visitor.visit(*this); }
void LogNode::accept(DiffVisitor& visitor) const { visitor.visit(*this); }

// Visitor implementations
void EvalVisitor::visit(const NumNode& node) {
    result = node.value;
}

void EvalVisitor::visit(const VarNode& node) {
    auto it = env.find(node.name);
    if (it == env.end()) {
        throw std::out_of_range("Unknown variable: " + node.name);
    }
    result = it->second;
}

void EvalVisitor::visit(const AddNode& node) {
    node.left->accept(*this);
    double left_result = result;
    node.right->accept(*this);
    result = left_result + result;
}

void EvalVisitor::visit(const SubNode& node) {
    node.left->accept(*this);
    double left_result = result;
    node.right->accept(*this);
    result = left_result - result;
}

void EvalVisitor::visit(const MulNode& node) {
    node.left->accept(*this);
    double left_result = result;
    node.right->accept(*this);
    result = left_result * result;
}

void EvalVisitor::visit(const NegNode& node) {
    node.operand->accept(*this);
    result = -result;
}

void EvalVisitor::visit(const PowNode& node) {
    node.base->accept(*this);
    double base_result = result;
    result = std::pow(base_result, node.exponent);
}

void EvalVisitor::visit(const ExpNode& node) {
    node.operand->accept(*this);
    result = std::exp(result);
}

void EvalVisitor::visit(const LogNode& node) {
    node.operand->accept(*this);
    result = std::log(result);
}

void PrintVisitor::visit(const NumNode& node) {
    std::ostringstream oss;
    oss.precision(17);  // High precision for double
    oss << node.value;
    result = oss.str();
}

void PrintVisitor::visit(const VarNode& node) {
    result = node.name;
}

void PrintVisitor::visit(const AddNode& node) {
    int current_precedence = 1;  // Addition precedence
    bool need_parens_left = (node.left->precedence < current_precedence);
    bool need_parens_right = (node.right->precedence < current_precedence);

    if (need_parens_left) {
        result = "(" + node.left->print() + ") + ";
    } else {
        result = node.left->print() + " + ";
    }

    if (need_parens_right) {
        result += "(" + node.right->print() + ")";
    } else {
        result += node.right->print();
    }
}

void PrintVisitor::visit(const SubNode& node) {
    int current_precedence = 1;  // Subtraction precedence
    bool need_parens_left = (node.left->precedence < current_precedence);
    bool need_parens_right = (node.right->precedence < current_precedence);

    if (need_parens_left) {
        result = "(" + node.left->print() + ") - ";
    } else {
        result = node.left->print() + " - ";
    }

    if (need_parens_right) {
        result += "(" + node.right->print() + ")";
    } else {
        result += node.right->print();
    }
}

void PrintVisitor::visit(const MulNode& node) {
    int current_precedence = 2;  // Multiplication precedence
    bool need_parens_left = (node.left->precedence < current_precedence);
    bool need_parens_right = (node.right->precedence < current_precedence);

    if (need_parens_left) {
        result = "(" + node.left->print() + ") * ";
    } else {
        result = node.left->print() + " * ";
    }

    if (need_parens_right) {
        result += "(" + node.right->print() + ")";
    } else {
        result += node.right->print();
    }
}

void PrintVisitor::visit(const NegNode& node) {
    int current_precedence = 3;  // Unary minus precedence
    bool need_parens = (node.operand->precedence < current_precedence);

    if (need_parens) {
        result = "-(" + node.operand->print() + ")";
    } else {
        result = "-" + node.operand->print();
    }
}

void PrintVisitor::visit(const PowNode& node) {
    int current_precedence = 4;  // Power precedence
    bool need_parens_left = (node.base->precedence < current_precedence);

    if (need_parens_left) {
        result = "(" + node.base->print() + ")^" + std::to_string(node.exponent);
    } else {
        result = node.base->print() + "^" + std::to_string(node.exponent);
    }
}

void PrintVisitor::visit(const ExpNode& node) {
    result = "exp(" + node.operand->print() + ")";
}

void PrintVisitor::visit(const LogNode& node) {
    result = "log(" + node.operand->print() + ")";
}

void VarsVisitor::visit(const NumNode& node) {
    // No variables in a number
}

void VarsVisitor::visit(const VarNode& node) {
    result.insert(node.name);
}

void VarsVisitor::visit(const AddNode& node) {
    node.left->accept(*this);
    node.right->accept(*this);
}

void VarsVisitor::visit(const SubNode& node) {
    node.left->accept(*this);
    node.right->accept(*this);
}

void VarsVisitor::visit(const MulNode& node) {
    node.left->accept(*this);
    node.right->accept(*this);
}

void VarsVisitor::visit(const NegNode& node) {
    node.operand->accept(*this);
}

void VarsVisitor::visit(const PowNode& node) {
    node.base->accept(*this);
}

void VarsVisitor::visit(const ExpNode& node) {
    node.operand->accept(*this);
}

void VarsVisitor::visit(const LogNode& node) {
    node.operand->accept(*this);
}

void CloneVisitor::visit(const NumNode& node) {
    result = std::make_unique<NumNode>(node.value);
}

void CloneVisitor::visit(const VarNode& node) {
    result = std::make_unique<VarNode>(node.name);
}

void CloneVisitor::visit(const AddNode& node) {
    node.left->accept(*this);
    Ptr left_clone = std::move(result);
    node.right->accept(*this);
    Ptr right_clone = std::move(result);
    result = std::make_unique<AddNode>(std::move(left_clone), std::move(right_clone));
}

void CloneVisitor::visit(const SubNode& node) {
    node.left->accept(*this);
    Ptr left_clone = std::move(result);
    node.right->accept(*this);
    Ptr right_clone = std::move(result);
    result = std::make_unique<SubNode>(std::move(left_clone), std::move(right_clone));
}

void CloneVisitor::visit(const MulNode& node) {
    node.left->accept(*this);
    Ptr left_clone = std::move(result);
    node.right->accept(*this);
    Ptr right_clone = std::move(result);
    result = std::make_unique<MulNode>(std::move(left_clone), std::move(right_clone));
}

void CloneVisitor::visit(const NegNode& node) {
    node.operand->accept(*this);
    Ptr operand_clone = std::move(result);
    result = std::make_unique<NegNode>(std::move(operand_clone));
}

void CloneVisitor::visit(const PowNode& node) {
    node.base->accept(*this);
    Ptr base_clone = std::move(result);
    result = std::make_unique<PowNode>(std::move(base_clone), node.exponent);
}

void CloneVisitor::visit(const ExpNode& node) {
    node.operand->accept(*this);
    Ptr operand_clone = std::move(result);
    result = std::make_unique<ExpNode>(std::move(operand_clone));
}

void CloneVisitor::visit(const LogNode& node) {
    node.operand->accept(*this);
    Ptr operand_clone = std::move(result);
    result = std::make_unique<LogNode>(std::move(operand_clone));
}

void FoldVisitor::visit(const NumNode& node) {
    result = std::make_unique<NumNode>(node.value);
}

void FoldVisitor::visit(const VarNode& node) {
    result = std::make_unique<VarNode>(node.name);
}

void FoldVisitor::visit(const AddNode& node) {
    node.left->accept(*this);
    Ptr left_folded = std::move(result);
    node.right->accept(*this);
    Ptr right_folded = std::move(result);

    // Try to fold constants
    if (auto* left_num = dynamic_cast<NumNode*>(left_folded.get())) {
        if (auto* right_num = dynamic_cast<NumNode*>(right_folded.get())) {
            result = std::make_unique<NumNode>(left_num->value + right_num->value);
            return;
        }
    }

    result = std::make_unique<AddNode>(std::move(left_folded), std::move(right_folded));
}

void FoldVisitor::visit(const SubNode& node) {
    node.left->accept(*this);
    Ptr left_folded = std::move(result);
    node.right->accept(*this);
    Ptr right_folded = std::move(result);

    // Try to fold constants
    if (auto* left_num = dynamic_cast<NumNode*>(left_folded.get())) {
        if (auto* right_num = dynamic_cast<NumNode*>(right_folded.get())) {
            result = std::make_unique<NumNode>(left_num->value - right_num->value);
            return;
        }
    }

    result = std::make_unique<SubNode>(std::move(left_folded), std::move(right_folded));
}

void FoldVisitor::visit(const MulNode& node) {
    node.left->accept(*this);
    Ptr left_folded = std::move(result);
    node.right->accept(*this);
    Ptr right_folded = std::move(result);

    // Try to fold constants
    if (auto* left_num = dynamic_cast<NumNode*>(left_folded.get())) {
        if (auto* right_num = dynamic_cast<NumNode*>(right_folded.get())) {
            result = std::make_unique<NumNode>(left_num->value * right_num->value);
            return;
        }
    }

    result = std::make_unique<MulNode>(std::move(left_folded), std::move(right_folded));
}

void FoldVisitor::visit(const NegNode& node) {
    node.operand->accept(*this);
    Ptr operand_folded = std::move(result);

    // Try to fold constants
    if (auto* num_node = dynamic_cast<NumNode*>(operand_folded.get())) {
        result = std::make_unique<NumNode>(-num_node->value);
        return;
    }

    result = std::make_unique<NegNode>(std::move(operand_folded));
}

void FoldVisitor::visit(const PowNode& node) {
    node.base->accept(*this);
    Ptr base_folded = std::move(result);

    // Try to fold constants
    if (auto* base_num = dynamic_cast<NumNode*>(base_folded.get())) {
        result = std::make_unique<NumNode>(std::pow(base_num->value, node.exponent));
        return;
    }

    result = std::make_unique<PowNode>(std::move(base_folded), node.exponent);
}

void FoldVisitor::visit(const ExpNode& node) {
    node.operand->accept(*this);
    Ptr operand_folded = std::move(result);

    // Try to fold constants
    if (auto* num_node = dynamic_cast<NumNode*>(operand_folded.get())) {
        result = std::make_unique<NumNode>(std::exp(num_node->value));
        return;
    }

    result = std::make_unique<ExpNode>(std::move(operand_folded));
}

void FoldVisitor::visit(const LogNode& node) {
    node.operand->accept(*this);
    Ptr operand_folded = std::move(result);

    // Try to fold constants
    if (auto* num_node = dynamic_cast<NumNode*>(operand_folded.get())) {
        result = std::make_unique<NumNode>(std::log(num_node->value));
        return;
    }

    result = std::make_unique<LogNode>(std::move(operand_folded));
}

void DiffVisitor::visit(const NumNode& node) {
    result = std::make_unique<NumNode>(0.0);
}

void DiffVisitor::visit(const VarNode& node) {
    if (node.name == variable) {
        result = std::make_unique<NumNode>(1.0);
    } else {
        result = std::make_unique<NumNode>(0.0);
    }
}

void DiffVisitor::visit(const AddNode& node) {
    node.left->accept(*this);
    Ptr left_diff = std::move(result);
    node.right->accept(*this);
    Ptr right_diff = std::move(result);
    result = std::make_unique<AddNode>(std::move(left_diff), std::move(right_diff));
}

void DiffVisitor::visit(const SubNode& node) {
    node.left->accept(*this);
    Ptr left_diff = std::move(result);
    node.right->accept(*this);
    Ptr right_diff = std::move(result);
    result = std::make_unique<SubNode>(std::move(left_diff), std::move(right_diff));
}

void DiffVisitor::visit(const MulNode& node) {
    // Product rule: (f * g)' = f' * g + f * g'
    node.left->accept(*this);
    Ptr left_diff = std::move(result);
    node.right->accept(*this);
    Ptr right_diff = std::move(result);

    Ptr left_term = std::make_unique<MulNode>(std::move(left_diff), node.right->clone());
    Ptr right_term = std::make_unique<MulNode>(node.left->clone(), std::move(right_diff));
    result = std::make_unique<AddNode>(std::move(left_term), std::move(right_term));
}

void DiffVisitor::visit(const NegNode& node) {
    node.operand->accept(*this);
    Ptr operand_diff = std::move(result);
    result = std::make_unique<NegNode>(std::move(operand_diff));
}

void DiffVisitor::visit(const PowNode& node) {
    // Power rule: (f^n)' = n * f^(n-1) * f'
    if (node.exponent == 0.0) {
        result = std::make_unique<NumNode>(0.0);
        return;
    }

    node.base->accept(*this);
    Ptr base_diff = std::move(result);

    // Create the derivative: n * base^(n-1) * base'
    Ptr base_pow = std::make_unique<PowNode>(node.base->clone(), node.exponent - 1);
    Ptr coeff = std::make_unique<NumNode>(node.exponent);
    Ptr term1 = std::make_unique<MulNode>(std::move(coeff), std::move(base_pow));
    result = std::make_unique<MulNode>(std::move(term1), std::move(base_diff));
}

void DiffVisitor::visit(const ExpNode& node) {
    // Derivative of exp(f) is exp(f) * f'
    node.operand->accept(*this);
    Ptr operand_diff = std::move(result);
    result = std::make_unique<MulNode>(std::make_unique<ExpNode>(node.operand->clone()), std::move(operand_diff));
}

void DiffVisitor::visit(const LogNode& node) {
    // Derivative of log(f) is (1/f) * f'
    node.operand->accept(*this);
    Ptr operand_diff = std::move(result);
    Ptr one = std::make_unique<NumNode>(1.0);
    Ptr reciprocal = std::make_unique<MulNode>(std::move(one), node.operand->clone());
    result = std::make_unique<MulNode>(std::move(reciprocal), std::move(operand_diff));
}

// Factory functions
Ptr num(double v) {
    return std::make_unique<NumNode>(v);
}

Ptr var(std::string name) {
    return std::make_unique<VarNode>(std::move(name));
}

Ptr add(Ptr a, Ptr b) {
    return std::make_unique<AddNode>(std::move(a), std::move(b));
}

Ptr sub(Ptr a, Ptr b) {
    return std::make_unique<SubNode>(std::move(a), std::move(b));
}

Ptr mul(Ptr a, Ptr b) {
    return std::make_unique<MulNode>(std::move(a), std::move(b));
}

Ptr neg(Ptr a) {
    return std::make_unique<NegNode>(std::move(a));
}

Ptr pow_(Ptr base, double exponent) {
    return std::make_unique<PowNode>(std::move(base), exponent);
}

Ptr exp_(Ptr a) {
    return std::make_unique<ExpNode>(std::move(a));
}

Ptr log_(Ptr a) {
    return std::make_unique<LogNode>(std::move(a));
}

// Free functions
double eval(const Node& n, const Env& env) {
    EvalVisitor visitor(env);
    n.accept(visitor);
    return visitor.result;
}

std::string print(const Node& n) {
    PrintVisitor visitor;
    n.accept(visitor);
    return visitor.get_result();
}

std::set<std::string> vars(const Node& n) {
    VarsVisitor visitor;
    n.accept(visitor);
    return visitor.get_result();
}

Ptr clone(const Node& n) {
    CloneVisitor visitor;
    n.accept(visitor);
    return std::move(visitor.get_result());
}

Ptr fold(const Node& n) {
    FoldVisitor visitor;
    n.accept(visitor);
    return std::move(visitor.get_result());
}

Ptr diff(const Node& n, const std::string& x) {
    DiffVisitor visitor(x);
    n.accept(visitor);
    return std::move(visitor.get_result());
}
}  // namespace ast

